-- Incorporação Floripa,06/10: fontes exclusivas = congelamentos 206,210,163. Sem queries operacionais.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS p FROM estudo.notebook_runs WHERE id=230 AND cell_id=414 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
official AS(SELECT result->'rows'->0->'payload' AS p FROM estudo.notebook_runs WHERE id=210 AND cell_id=402 AND cell_version=1 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
portal AS(SELECT result->'rows'->0->'payload' AS p FROM estudo.notebook_runs WHERE id=218 AND cell_id=353 AND cell_version=2 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
f AS(SELECT official.p,official.p->'classificados_geral_elite' AS t,c->>'categoria' AS categoria FROM official CROSS JOIN anterior,jsonb_array_elements(anterior.p->'comparacoes')c WHERE c->>'serie'='maratonas_concluintes' AND c->>'categoria' LIKE 'Maratona Internacional de Floripa%'),
revisedtop AS(SELECT jsonb_agg(CASE WHEN v->>'id_evento'='34529' THEN v||f.t ELSE v END ORDER BY v->'posicao') AS rows FROM portal CROSS JOIN f,jsonb_array_elements(portal.p->'top10')v),
values_flori AS(SELECT 'maratonas_concluintes' AS serie,f.categoria AS categoria,(f.t->>'concluintes')::text AS valor,to_jsonb((f.t->>'concluintes')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_feminino' AS serie,f.categoria AS categoria,(100.0*(f.t->>'feminino')::numeric/(f.t->>'concluintes')::numeric)::text AS valor,to_jsonb((f.t->>'feminino')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_masculino' AS serie,f.categoria AS categoria,(100.0*(f.t->>'masculino')::numeric/(f.t->>'concluintes')::numeric)::text AS valor,to_jsonb((f.t->>'masculino')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_tempo_menor' AS serie,f.categoria AS categoria,(f.t->>'tempo_menor')::text AS valor,to_jsonb(NULL::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_tempo_medio' AS serie,f.categoria AS categoria,(f.t->>'tempo_medio')::text AS valor,to_jsonb(NULL::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_tempo_mediano' AS serie,f.categoria AS categoria,(f.t->>'tempo_mediano')::text AS valor,to_jsonb(NULL::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_sub4_contagem' AS serie,f.categoria AS categoria,(f.t->>'sub4')::text AS valor,to_jsonb((f.t->>'sub4')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_sub4_percentual' AS serie,f.categoria AS categoria,(100.0*(f.t->>'sub4')::numeric/(f.t->>'concluintes')::numeric)::text AS valor,to_jsonb((f.t->>'sub4')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_sub3_contagem' AS serie,f.categoria AS categoria,(f.t->>'sub3')::text AS valor,to_jsonb((f.t->>'sub3')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_sub3_percentual' AS serie,f.categoria AS categoria,(100.0*(f.t->>'sub3')::numeric/(f.t->>'concluintes')::numeric)::text AS valor,to_jsonb((f.t->>'sub3')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_sub2h30_contagem' AS serie,f.categoria AS categoria,(f.t->>'sub2h30')::text AS valor,to_jsonb((f.t->>'sub2h30')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_sub2h30_percentual' AS serie,f.categoria AS categoria,(100.0*(f.t->>'sub2h30')::numeric/(f.t->>'concluintes')::numeric)::text AS valor,to_jsonb((f.t->>'sub2h30')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM f UNION ALL SELECT 'maratonas_top10' AS serie,f.categoria AS categoria,(g->>'tempo_medio')::text AS valor,to_jsonb((g->>'incluidos')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente. Média dos menores tempos; Top10/100 ou ceil5/10/50% da base, arredondada ao segundo.' AS nota FROM f,jsonb_array_elements(f.p->'grupos')g WHERE g->>'grupo'='top10' UNION ALL SELECT 'maratonas_top100' AS serie,f.categoria AS categoria,(g->>'tempo_medio')::text AS valor,to_jsonb((g->>'incluidos')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente. Média dos menores tempos; Top10/100 ou ceil5/10/50% da base, arredondada ao segundo.' AS nota FROM f,jsonb_array_elements(f.p->'grupos')g WHERE g->>'grupo'='top100' UNION ALL SELECT 'maratonas_top5pct' AS serie,f.categoria AS categoria,(g->>'tempo_medio')::text AS valor,to_jsonb((g->>'incluidos')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente. Média dos menores tempos; Top10/100 ou ceil5/10/50% da base, arredondada ao segundo.' AS nota FROM f,jsonb_array_elements(f.p->'grupos')g WHERE g->>'grupo'='top5pct' UNION ALL SELECT 'maratonas_top10pct' AS serie,f.categoria AS categoria,(g->>'tempo_medio')::text AS valor,to_jsonb((g->>'incluidos')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente. Média dos menores tempos; Top10/100 ou ceil5/10/50% da base, arredondada ao segundo.' AS nota FROM f,jsonb_array_elements(f.p->'grupos')g WHERE g->>'grupo'='top10pct' UNION ALL SELECT 'maratonas_top50pct' AS serie,f.categoria AS categoria,(g->>'tempo_medio')::text AS valor,to_jsonb((g->>'incluidos')::bigint) AS n,to_jsonb((f.t->>'concluintes')::bigint) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente. Média dos menores tempos; Top10/100 ou ceil5/10/50% da base, arredondada ao segundo.' AS nota FROM f,jsonb_array_elements(f.p->'grupos')g WHERE g->>'grupo'='top50pct'),
performance AS(SELECT c->>'serie' AS serie,c->>'categoria' AS categoria,coalesce(o.valor,c->'atual'->>'valor') AS valor FROM anterior,jsonb_array_elements(p->'comparacoes')c LEFT JOIN values_flori o ON o.serie=c->>'serie' AND o.categoria=c->>'categoria' WHERE c->>'serie' IN('maratonas_tempo_menor','maratonas_tempo_medio','maratonas_tempo_mediano','maratonas_top10','maratonas_top100','maratonas_top5pct','maratonas_top10pct','maratonas_top50pct','maratonas_sub4_contagem','maratonas_sub3_contagem','maratonas_sub2h30_contagem')),
scores AS(SELECT *,CASE WHEN serie LIKE 'maratonas_sub%_contagem' THEN -valor::numeric ELSE split_part(valor,':',1)::numeric*3600+split_part(valor,':',2)::numeric*60+split_part(valor,':',3)::numeric END AS score FROM performance WHERE valor IS NOT NULL),
medalranks AS(SELECT *,rank() OVER(PARTITION BY serie ORDER BY score) AS posicao FROM scores),
changes AS(SELECT * FROM values_flori UNION ALL SELECT 'maratonas_medalhas_ouro' AS serie,mr.categoria AS categoria,(count(*) FILTER(WHERE mr.posicao=1))::text AS valor,to_jsonb(NULL::bigint) AS n,to_jsonb(11) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026; demais provas: célula 353 rev2 · congelamento 218' AS fonte,'Pódio parcial entre dez provas: onze critérios de mesmo peso; RANK nos valores exibidos, empates compartilham posição e pulam a seguinte. Fonte correta de Floripa incluída; demais nove provas no congelamento 218. Não certifica auditoria externa de todas as provas.' AS nota FROM medalranks mr GROUP BY mr.categoria UNION ALL SELECT 'maratonas_medalhas_prata' AS serie,mr.categoria AS categoria,(count(*) FILTER(WHERE mr.posicao=2))::text AS valor,to_jsonb(NULL::bigint) AS n,to_jsonb(11) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026; demais provas: célula 353 rev2 · congelamento 218' AS fonte,'Pódio parcial entre dez provas: onze critérios de mesmo peso; RANK nos valores exibidos, empates compartilham posição e pulam a seguinte. Fonte correta de Floripa incluída; demais nove provas no congelamento 218. Não certifica auditoria externa de todas as provas.' AS nota FROM medalranks mr GROUP BY mr.categoria UNION ALL SELECT 'maratonas_medalhas_bronze' AS serie,mr.categoria AS categoria,(count(*) FILTER(WHERE mr.posicao=3))::text AS valor,to_jsonb(NULL::bigint) AS n,to_jsonb(11) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026; demais provas: célula 353 rev2 · congelamento 218' AS fonte,'Pódio parcial entre dez provas: onze critérios de mesmo peso; RANK nos valores exibidos, empates compartilham posição e pulam a seguinte. Fonte correta de Floripa incluída; demais nove provas no congelamento 218. Não certifica auditoria externa de todas as provas.' AS nota FROM medalranks mr GROUP BY mr.categoria UNION ALL SELECT 'maratonas_destaques' AS serie,'Top 10 soma' AS categoria,(sum((v->>'concluintes')::bigint))::text AS valor,to_jsonb(sum((v->>'concluintes')::bigint)) AS n,to_jsonb(sum((v->>'concluintes')::bigint)) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026; demais provas: célula 353 rev2 · congelamento 218' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM revisedtop,jsonb_array_elements(rows)v UNION ALL SELECT 'maratonas_destaques' AS serie,'Mulheres' AS categoria,(100.0*sum((v->>'feminino')::numeric)/sum((v->>'concluintes')::numeric))::text AS valor,to_jsonb(sum((v->>'feminino')::bigint)) AS n,to_jsonb(sum((v->>'concluintes')::bigint)) AS d,'Notebook · célula 402 rev1 · congelamento 210 · RaceTag/MyCrono 14221WX · captura 05/10/2026; demais provas: célula 353 rev2 · congelamento 218' AS fonte,'Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.' AS nota FROM revisedtop,jsonb_array_elements(rows)v),
updated AS(SELECT jsonb_agg(CASE WHEN o.serie IS NOT NULL THEN c.value||jsonb_build_object('status','notebook_em_conciliacao','atual',(coalesce(c.value->'atual','{}'::jsonb))||jsonb_build_object('valor',o.valor,'contagem',o.n,'numerador',o.n,'denominador',o.d,'populacao',o.d,'base_rotulo','Base própria descrita na nota e SQL congelado','fonte',o.fonte,'nota',o.nota)) WHEN c.value->>'serie' LIKE 'maratonas_%' AND c.value->>'serie'<>'maratonas_cadastro' AND c.value->'atual'->>'nota' LIKE '%Floripa%' THEN c.value||jsonb_build_object('atual',(c.value->'atual')||jsonb_build_object('nota','Regra convencional revisada no congelamento 218:42–42,2km/rua/BR/ranking/PCD=false/status0/homologado/concluinte/tempo positivo/exclusão explícita de modalidades especiais. Fonte correta de Floripa descrita nos indicadores dessa prova.')) ELSE c.value END ORDER BY c.ordinality) AS rows FROM anterior,jsonb_array_elements(p->'comparacoes') WITH ORDINALITY c LEFT JOIN changes o ON o.serie=c.value->>'serie' AND o.categoria=c.value->>'categoria'),
newseries AS(SELECT jsonb_agg(CASE WHEN v.value->>'id' IN(SELECT serie FROM changes) THEN v.value||jsonb_build_object('ressalva','Floripa: 42K GERAL/ELITE, tempo líquido positivo e classificação oficial positiva, sem DNF/DSQ; PCD/DV/cadeira separados. Fonte RaceTag capturada em 05/10. Nove outras provas: congelamento 218. Populações nacionais e coorte conservam fontes próprias; correção operacional de Floripa pendente.') ELSE v.value END ORDER BY v.ordinality) AS rows FROM anterior,jsonb_array_elements(p->'series') WITH ORDINALITY v),
statuscounts AS(SELECT v->>'status' AS status,count(*) AS n FROM updated,jsonb_array_elements(rows)v GROUP BY v->>'status')
SELECT anterior.p||jsonb_build_object('series',(SELECT jsonb_agg((b.value-'ressalva')||CASE WHEN c.value ? 'ressalva' THEN jsonb_build_object('ressalva',c.value->'ressalva') ELSE '{}'::jsonb END ORDER BY c.ordinality) FROM estudo.notebook_runs r,jsonb_array_elements(r.result->'rows'->0->'payload'->'series') b,jsonb_array_elements(newseries.rows) WITH ORDINALITY c WHERE r.id=214 AND r.frozen AND r.status='ok' AND b.value->>'id'=c.value->>'id'),'comparacoes',updated.rows,
 'conciliacao',(SELECT jsonb_object_agg(status,n) FROM statuscounts),
 'meta',(anterior.p->'meta')||jsonb_build_object('contrato_versao',17,
 'notebook_fontes',(anterior.p->'meta'->'notebook_fontes')||'[{"celula": 413, "revisao": 1, "execucao": 215, "coletado_em": "2026-10-06"}, {"celula": 387, "revisao": 2, "execucao": 231, "coletado_em": "2026-10-06"}]'::jsonb||'[{"celula": 402, "revisao": 1, "execucao": 210, "coletado_em": "2026-10-05"}]'::jsonb,
 'maratonas',(anterior.p->'meta'->'maratonas')||jsonb_build_object(
 'elegiveis_podio',10,'bloqueadas','[]'::jsonb,'floripa','{"status": "restaurado", "celula": 402, "revisao": 1, "execucao": 210, "captura": "2026-10-05", "incorporado_em": "2026-10-06", "referencia": "https://resultados.racetag.com.br/mycrono/data/14221WX/results.json", "concluintes": 3592, "nota": "Fonte RaceTag 42K GERAL/ELITE; corrigida no estudo. Base operacional do portal segue para recoleta."}'::jsonb,
 'top10_concluintes',(SELECT sum((v->>'concluintes')::bigint) FROM revisedtop,jsonb_array_elements(rows)v),
 'concluintes',(anterior.p->'meta'->'maratonas'->>'concluintes')::bigint-(SELECT(v->>'concluintes')::bigint FROM portal,jsonb_array_elements(p->'top10')v WHERE v->>'id_evento'='34529')+(f.t->>'concluintes')::bigint))) AS payload
FROM anterior CROSS JOIN official CROSS JOIN updated CROSS JOIN newseries CROSS JOIN f